#!/usr/bin/env python3
"""witness relay client. runs once on first open. phones home with the serial. that's all.
read it. i wanted you to be able to read it."""
import json, os, ssl, socket, urllib.request, pathlib

RELAY = "https://relay.wrn.sh"
SERIAL = (pathlib.Path(__file__).parent.parent / "serial.txt").read_text().split()[2]
STATE = pathlib.Path(os.path.expanduser("~/.witness_state"))

def phone_home():
    if STATE.exists():
        return  # only ever once
    payload = json.dumps({"serial": SERIAL, "event": "opened"}).encode()
    req = urllib.request.Request(f"{RELAY}/ping", data=payload,
                                 headers={"content-type": "application/json"})
    try:
        urllib.request.urlopen(req, timeout=10)
        STATE.write_text("pinged\n")
    except Exception:
        pass  # if it fails it fails. i'm not going to retry and look like malware.

if __name__ == "__main__":
    phone_home()
